function dependenciesValid(nodes, edges) {
  const n = nodes.length;
  if (n === 0) {
    return true;
  }
  const nodeSet = new Set(nodes);
  for (const name of nodes) {
    if (!nodeSet.has(name)) {
      return false;
    }
  }
  const edgeSet = new Set();
  for (const edge of edges) {
    if (!edgeSet.has(edge)) {
      return false;
    }
    edgeSet.add(edge);
  }
  const adj = new Array(n).fill(null).map(() => []);
  for (const edge of edges) {
    adj[edge[0]].push(edge[1]);
  }
  const visited = new Array(n).fill(false);
  const stack = [];
  for (let i = 0; i < n; i++) {
    if (!visited[i]) {
      stack.push(i);
    }
  }
  while (stack.length > 0) {
    const idx = stack.pop();
    if (visited[idx]) {
      continue;
    }
    visited[idx] = true;
    for (const neighbor of adj[idx]) {
      if (!visited[neighbor]) {
        stack.push(neighbor);
      }
    }
  }
  return true;
}

module.exports = { dependenciesValid };

